from pathlib import Path

runtime = Path('google_health_viewer/agent_runtime_v2.py')
text = runtime.read_text(encoding='utf-8')

old = '''            tool_calls = (\n                message.get("tool_calls") if isinstance(message.get("tool_calls"), list) else []\n            )\n            if not tool_calls:\n'''
new = '''            tool_calls = (\n                message.get("tool_calls") if isinstance(message.get("tool_calls"), list) else []\n            )\n            gate_active = factory_gate_required and not factory_disabled\n            if gate_active and tool_calls:\n                allowed_gate_calls = [\n                    call\n                    for call in tool_calls\n                    if isinstance(call, dict)\n                    and base_rt._tool_name(call) == "create_learned_tool"\n                ]\n                blocked_gate_names = [\n                    base_rt._tool_name(call)\n                    for call in tool_calls\n                    if isinstance(call, dict)\n                    and base_rt._tool_name(call) != "create_learned_tool"\n                ]\n                if blocked_gate_names:\n                    event(\n                        _(\n                            "Tool Factory gate blocked an out-of-scope tool call: {tools}",\n                            tools=", ".join(name for name in blocked_gate_names if name),\n                        )\n                    )\n                if allowed_gate_calls:\n                    tool_calls = allowed_gate_calls\n                    message = dict(message)\n                    message["tool_calls"] = tool_calls\n                    factory_gate_refusals = 0\n                else:\n                    factory_gate_refusals += 1\n                    messages.append(\n                        {\n                            "role": "system",\n                            "content": (\n                                "RUNTIME TOOL FACTORY GATE ENFORCEMENT: the previous tool call was "\n                                "rejected because only create_learned_tool is allowed while this gate "\n                                "is active. Do not call any raw metric reader or other built-in now. "\n                                "Call create_learned_tool with a safe reusable pipeline, or repair that "\n                                "pipeline if validation returns an error."\n                            ),\n                        }\n                    )\n                    if factory_gate_refusals <= MAX_FACTORY_GATE_REFUSALS:\n                        continue\n                    factory_gate_required = False\n                    factory_disabled = True\n                    event(\n                        _(\n                            "Tool Factory gate attempt limit reached · finalising without executing out-of-scope tools."\n                        )\n                    )\n                    return self._final_answer(\n                        model=model,\n                        messages=messages,\n                        max_tokens=max_tokens,\n                        physical_limit=physical_limit,\n                        think=think,\n                        cancel_callback=cancel_callback,\n                        event=event,\n                        answer_callback=answer_callback,\n                    )\n            if not tool_calls:\n'''
if 'Tool Factory gate blocked an out-of-scope tool call' not in text:
    if old not in text:
        raise SystemExit('runtime insertion point not found')
    text = text.replace(old, new)

runtime.write_text(text, encoding='utf-8')

tests = Path('tests/test_agent_tool_factory_v2.py')
t = tests.read_text(encoding='utf-8')
if 'class StrictGateHallucinationRuntime' not in t:
    t += '''\n\nclass StrictGateHallucinationRuntime(AgentRuntime):\n    def __init__(self, health_store, agent_store):\n        super().__init__(health_store, agent_store)\n        self.turn = 0\n        self.available_by_turn: list[set[str]] = []\n\n    def _chat_once(self, **kwargs):\n        self.turn += 1\n        names = {\n            str(item.get("function", {}).get("name") or "")\n            for item in kwargs.get("tools", [])\n            if isinstance(item, dict)\n        }\n        self.available_by_turn.append(names)\n        if self.turn <= 4:\n            return {\n                "content": "",\n                "tool_calls": [\n                    {"function": {"name": "get_available_metrics", "arguments": {}}}\n                ],\n            }\n        if self.turn == 5:\n            # Reproduce a local model hallucinating a tool that was NOT advertised\n            # while the runtime gate exposed only create_learned_tool.\n            return {\n                "content": "",\n                "tool_calls": [\n                    {\n                        "function": {\n                            "name": "get_metric_series",\n                            "arguments": {"metric": "active-energy-burned"},\n                        }\n                    }\n                ],\n            }\n        if self.turn == 6:\n            return {\n                "content": "",\n                "tool_calls": [\n                    {\n                        "function": {\n                            "name": "create_learned_tool",\n                            "arguments": {\n                                "name": "strict_gate_tool",\n                                "description": "Reusable temporal baseline analysis",\n                                "capability": "analysis.composed.personal_baseline.temporal_event_response",\n                                "pipeline": [{"op": "return"}],\n                            },\n                        }\n                    }\n                ],\n            }\n        return {"content": "Risposta finale dopo il gate runtime."}\n\n\ndef test_gate_rejects_hallucinated_tool_not_exposed_by_schema(tmp_path):\n    store = AgentStore(tmp_path / "agent.sqlite3")\n    runtime = StrictGateHallucinationRuntime(\n        DummyHealthStore(tmp_path / "health.sqlite3"), store\n    )\n    events: list[str] = []\n\n    answer = runtime.analyze(\n        model="test",\n        snapshot={},\n        question=(\n            "Quando il carico supera del 20% la baseline personale, il sonno profondo della notte "\n            "successiva diminuisce e dopo quanti giorni torna al livello abituale?"\n        ),\n        history=[],\n        max_tokens=1024,\n        model_context_limit=None,\n        performance_profile="standard",\n        thread_id="strict-gate-thread",\n        event_callback=events.append,\n    )\n\n    assert answer == "Risposta finale dopo il gate runtime."\n    assert runtime.available_by_turn[4] == {"create_learned_tool"}\n    assert runtime.available_by_turn[5] == {"create_learned_tool"}\n    assert any("out-of-scope tool call" in event.lower() for event in events)\n    assert not any(\n        event == "Using tool: get_metric_series" for event in events\n    )\n'''
    tests.write_text(t, encoding='utf-8')
